        return receiver.endswith(args[0])
    if name == "replace":
        return receiver.replace(args[0], args[1])
    if name == "split":
        return receiver.split(*args)
    if name == "join":
        return receiver.join(args[0])
    if name == "count":
        return receiver.count(args[0])

